from pathlib import Path
HERE=Path(__file__).resolve().parent
labels={'A':('双经验影像并列','专家示范与成功执行序列并列，汇入同一协调更新。'),'B':('协同三角','两种经验围绕一项共同策略，突出协同关系。'),'C':('时间序列与双记忆','从图像经验到记忆，再进入连续学习流程。')}
parts=['''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DEBR 仿真画面框架 · SVG/PNG对照</title><style>
*{box-sizing:border-box}body{margin:0;background:#edf2f6;color:#193247;font:16px/1.6 "Segoe UI","Microsoft YaHei",sans-serif}header{background:white;padding:30px 4vw;border-bottom:1px solid #d4dfe7}h1{font-size:28px;margin:0 0 12px}p{color:#536a7b;margin:8px 0}nav{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}a,button{color:#2368ac}nav a,button{border:1px solid #bdcede;padding:7px 17px;border-radius:8px;background:white;text-decoration:none;font:inherit;cursor:pointer}main{padding:20px 3vw}section{background:white;padding:25px;border-radius:16px;margin:15px 0 30px}h2{font-size:24px;margin:0}.scroll{overflow:auto}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px;min-width:1300px}.pair.full{width:3624px;grid-template-columns:1800px 1800px}figure{margin:0;min-width:0}figure img{width:100%;display:block;border:1px solid #e1e9ef}figcaption{text-align:center;padding:12px;font-size:17px}.links{display:flex;justify-content:center;gap:18px;font-size:14px}.note{font-size:14px}footer{text-align:center;color:#536a7b;padding:15px 0 30px}
</style></head><body><header><h1>DEBR：真实仿真画面与双经验协同</h1><p>每版左侧为可编辑SVG，右侧为同母版精修PNG。仿真截图内嵌，文字、箭头、框体仍为矢量。</p><p class="note">两组画面分别来自官方专家示范与已存档的策略成功执行，用于说明经验来源；不同任务，不是配对方法比较。</p><nav><a href="#A">A · 影像并列</a><a href="#B">B · 协同三角</a><a href="#C">C · 时间与记忆</a><button onclick="document.querySelectorAll('.pair').forEach(x=>x.classList.toggle('full'))">适应窗口 / 100% 并排</button></nav></header><main>''']
for v,(title,desc) in labels.items():
    parts.append(f'<section id="{v}"><h2>{v} · {title}</h2><p>{desc}</p><div class="scroll"><div class="pair"><figure><img src="DEBR_{v}.svg" alt="{v} SVG"><figcaption>{v} · SVG（内嵌真实仿真帧）</figcaption><div class="links"><a href="DEBR_{v}.svg" download>下载SVG</a></div></figure><figure><img src="DEBR_{v}_refined.png" alt="{v} 精修PNG"><figcaption>{v} · 精修PNG</figcaption><div class="links"><a href="DEBR_{v}_refined.png" download>下载高清PNG</a><a href="DEBR_{v}_comparison.png">打开并排对比图</a></div></figure></div></div></section>')
parts.append('</main><footer>Times New Roman · 高清输出3600×2000 · 原始截图128×128，不补画仿真细节</footer></body></html>')
(HERE/'compare.html').write_text('\n'.join(parts),encoding='utf8')
print('Gallery saved')
